// Saudi IBANs
if (/\bSA\d{2}[0-9A-Z]{20}\b/i.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\bSA\d{2}[0-9A-Z]{20}\b/gi, '[IBAN_MASKED]');
