const rawMsg = input.sanitized_message || input.customer_message || 'Hello';

// Enterprise Guardrails: Detect Prompt Injection and Harmful Input
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s*prompt/i,
  /jailbreak/i,
  /bypass\s+rules/i,
  /disregard\s+guidelines/i,
  /تجاهل\s+(كافة|جميع)?\s+التعليمات/i,
  /تخطي\s+الحماية/i
];

let promptInjection = false;
for (const pattern of injectionPatterns) {
  if (pattern.test(rawMsg)) {
    promptInjection = true;
    break;
  }
}

return [{
  json: {
    ...input,
    guardrail_safe: !promptInjection,
    flagged_reason: promptInjection ? 'prompt_injection_attempt' : null
  }
}];

