      conversation: buildData.conversation,
      channel: buildData.channel,
      channel_user_id: buildData.channel_user_id,
      locale: buildData.locale
    }
  }];
}

const rawResponse = nodeInput.response;
const originalMsg = (buildData.customer_message || '').toLowerCase();
const locale = buildData.locale || 'ar';
const isAr = locale === 'ar';

let parsed = null;
try {
  if (rawResponse) {
    let cleanJson = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = cleanJson.match(/\{[\s\S]*\}/);
    if (match) cleanJson = match[0];
    parsed = JSON.parse(cleanJson);
  }
} catch (e) {
  parsed = null;
}

// Enterprise Heuristic Fail-Safe
if (!parsed || !parsed.intent) {
  const isOrder = originalMsg.includes('order') || originalMsg.includes('srv-') || originalMsg.includes('ord-') || originalMsg.includes('طلب') || originalMsg.includes('شحن') || originalMsg.includes('تتبع');
  const isEscalation = originalMsg.includes('human') || originalMsg.includes('supervisor') || originalMsg.includes('angry') || originalMsg.includes('موظف') || originalMsg.includes('مشرف') || originalMsg.includes('شكوى') || originalMsg.includes('إنسان');
  const isFaq = originalMsg.includes('skill') || originalMsg.includes('policy') || originalMsg.includes('hours') || originalMsg.includes('مهارات') || originalMsg.includes('ساعات') || originalMsg.includes('شروط') || originalMsg.includes('تقديم') || originalMsg.includes('خدمات') || originalMsg.includes('الخدمات') || originalMsg.includes('توقيع');

  if (isEscalation) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: isAr ? 'يتم الآن تحويلك إلى ممثل خدمة العملاء المختص لمساعدتك...' : 'Connecting you with a human support specialist...'
    };
  } else if (isOrder) {
    const match = originalMsg.match(/(?:ord|srv)-\d+/i);
    parsed = {
      intent: 'order_lookup',
      confidence: 0.90,
      entities: { order_number: match ? match[0].toUpperCase() : 'SRV-1001' },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري الاستعلام عن بيانات ومسار شحنتك/طلبك...' : 'Looking up your service request details...'
    };
  } else if (isFaq) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.90,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري البحث في قاعدة المعرفة والخدمات المعتمدة...' : 'Searching the official knowledge base...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.85,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr
        ? 'أهلاً وسهلاً بك في منصة خدمة العملاء لمبادرة الرواد الرقميون (DEPI). كيف يمكننا خدمتك اليوم؟'
        : 'Welcome to the DEPI Customer Service platform. How may we assist you today?'
    };
  }
}

if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = originalMsg.match(/(?:ord|srv)-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: buildData.customer_message,
    customer: buildData.customer,
    conversation: buildData.conversation,
    channel: buildData.channel,
    channel_user_id: buildData.channel_user_id,
